using System;
using System.Collections.Generic;

public class DistributedNode
{
    public string NodeId { get; }
    public string Data { get; set; } = "Versi Awal";

    public DistributedNode(string nodeId) => NodeId = nodeId;
}

public class DistributedCluster
{
    private readonly List<DistributedNode> _nodes = new();

    public DistributedCluster(params string[] nodeIds)
    {
        foreach (var id in nodeIds) _nodes.Add(new DistributedNode(id));
    }

    public void WriteQuorum(string newData, int quorumSize)
    {
        if (quorumSize > _nodes.Count)
        {
            throw new InvalidOperationException("Gagal mencapai quorum CP!");
        }

        int written = 0;
        for (int i = 0; i < quorumSize; i++)
        {
            _nodes[i].Data = newData;
            written++;
        }

        Console.WriteLine($"Write Quorum Sukses: Berhasil mereplikasi ke {written} node.");
    }

    public void PrintClusterState()
    {
        foreach (var node in _nodes)
        {
            Console.WriteLine($"Node {node.NodeId}: {node.Data}");
        }
    }
}

public class Program
{
    public static void Main()
    {
        var cluster = new DistributedCluster("Node-1", "Node-2", "Node-3");

        Console.WriteLine("--- Status Awal ---");
        cluster.PrintClusterState();

        Console.WriteLine("\n--- Menulis dengan Quorum (2 dari 3) ---");
        cluster.WriteQuorum("Saldo: Rp 1.000.000", 2);
        cluster.PrintClusterState();
    }
}
